func TestIncludeByDefaultFalseBypassedByExactModelPin(t *testing.T) {
	in := excludedProviderInputs()
	dec, err := Resolve(Request{Model: "gpt-4o"}, in)
	if err != nil {
		t.Fatalf("Resolve with explicit model pin: %v", err)
	}
